"""Events V0.3 fixture. Reuses the v2 builder without regenerating its pages."""
from pathlib import Path
exec((Path(__file__).parent/'build-mockups.py').read_text().split('eventrows=')[0])
import calendar
name='Founder stories: building from zero'
def inp(label,value,kind='text'):
 return field(label,f'<input class="input" type="{kind}" value="{value}">')
rows=[]
for n,date,place,team,state,count in [(name,'Nov 12 · 6–8 PM','The Nest · Room 250','Entrepreneurship','Draft','—'),('Design for people','Nov 18 · 5–7 PM','ICICS 180','Design','Published','64 / 80'),('Coffee & cofounders','Nov 21 · 10–11:30 AM','UBC Life Building','Community','Published','38 / 40'),('Fall venture night','Oct 28 · 6–9 PM','Sauder HA 098','Community','Completed','112 / 120')]:
 rows.append([(f'<button class="linkish" data-open="editor">{n}</button>' if n==name else f'<span class="cell-title">{n}</span>')+f'<span class="cell-sub">{date}<br>{place}</span>',team,status(state,'attention' if state=='Draft' else 'positive'),count,button('Open kit',extra='data-open="handoff"') if n==name else ('Luma linked' if state=='Published' else 'CSV imported')])
listing=table(['Event · Vancouver time','Host','Status','Registered / capacity','Handoff'],rows,caption='Fall term events')
days=''.join(f'<div class="cal-dow">{d}</div>' for d in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'])
for week in calendar.Calendar().monthdayscalendar(2026,11):
 for d in week:
  event={12:name,18:'Design for people',21:'Coffee & cofounders'}.get(d)
  days+=f'<div class="cal-day {"is-outside" if not d else "is-today" if d==1 else ""}" aria-label="November {d or "outside month"}, {1 if event else 0} events"><span class="cal-date">{d or ""}</span>'+ (f'<button class="cal-event {"is-draft" if d==12 else ""}" {"data-open=editor" if d==12 else "disabled"}><span class="cal-event-title">{event}</span></button><span class="cal-dots" aria-hidden="true"><span></span></span>' if event else '')+'</div>'
agenda='<ul class="cal-agenda">'+''.join(f'<li><p class="cal-agenda-day">Nov {d} · {t}</p><button class="cal-event" {"data-open=editor" if d==12 else "disabled"}>{n}</button></li>' for d,t,n in [(12,'6–8 PM · Draft',name),(18,'5–7 PM','Design for people'),(21,'10–11:30 AM','Coffee & cofounders')])+'</ul>'
month='<div class="cal-month" role="group" aria-label="November 2026">'+days+'</div>'+agenda
week='<div class="cal-week"><div class="cal-week-corner"></div>'+''.join(f'<div class="cal-week-day">{d}<strong>{i+9}</strong></div>' for i,d in enumerate(['Mon','Tue','Wed','Thu','Fri','Sat','Sun']))+'<div class="cal-gutter" style="--rows:24">'+''.join(f'<span class="cal-hour" style="grid-row:{i*2+1}">{i+9}:00</span>' for i in range(12))+'</div>'+''.join('<div class="cal-col" style="--rows:24">'+(f'<button class="cal-block" style="--start:18;--len:4" data-open="editor"><span class="cal-block-title">Founder stories · Draft</span><span class="cal-block-time">6–8 PM</span></button>' if i==3 else '')+'</div>' for i in range(7))+'</div><ul class="cal-agenda"><li class="cal-agenda-day">Thu Nov 12 · 6–8 PM</li><li><button class="cal-event" data-open="editor">Founder stories · Draft</button></li></ul>'
controls='<div class="toolbar"><div class="toolbar-main">'+field('Search events','<input id="filter" class="input" type="search" placeholder="Name or location">')+'</div><div class="action-row">'+button('Import CSV',extra='data-open="import"')+button('New event',True,'data-open="editor" data-new')+'</div></div>'
views='<div class="cal-head"><h2 id="period">Fall term · 4 events</h2><div class="segmented" role="group" aria-label="Event view">'+''.join(f'<button class="segment" data-view="{v}" aria-pressed="{str(v=="list").lower()}">{v.title()}</button>' for v in ['list','month','week'])+'</div></div><section id="view-list">'+listing+'</section><section id="view-month" hidden class="cal"><h3 class="cal-title">November 2026</h3>'+month+'</section><section id="view-week" hidden class="cal"><h3 class="cal-title">November 9–15, 2026 · Vancouver</h3>'+week+'</section>'
editor='<p class="notice">Draft · Only saved in this workspace until you publish in Luma.</p><form id="event-form" class="stack">'+inp('Event name',name)+'<div class="grid-fields">'+inp('Starts · America/Vancouver','2026-11-12T18:00','datetime-local')+inp('Ends · America/Vancouver','2026-11-12T20:00','datetime-local')+'</div>'+inp('Location','The Nest · Room 250, UBC')+field('Host','<select class="select"><option>Entrepreneurship · Alex Chen</option><option>Design · Jordan Lee</option><option>Community · Maya Patel</option></select>')+field('Description','<textarea class="textarea">An honest conversation with UBC founders about finding a first customer, building a team, and starting before you feel ready. Q&amp;A and community introductions to follow.</textarea>')+inp('Capacity','100','number')+'<label class="dropzone">Cover image · JPG, PNG or WebP<input type="file" accept="image/jpeg,image/png,image/webp"></label><img class="event-cover" src="../img/buildher-wide.webp" alt="CSEED event cover preview"><p class="field-hint">Sample club photo. Replace with the approved Founder stories cover before publishing.</p><div class="action-row"><button class="btn btn--primary" type="submit">Save draft</button>'+button('Request design',extra='type="button" data-open="design"')+button('Delete event',extra='type="button" data-open="delete"')+'</div><p id="saved" role="status"></p></form>'
kit='<p class="notice notice--info">Publish manually in Luma. Copy each field, upload the cover, then paste the published URL below. No automatic sync.</p>'
for label,value in [('Name',name),('Time','November 12, 2026 · 6–8 PM · America/Vancouver'),('Location','The Nest · Room 250, UBC'),('Host','Entrepreneurship · Alex Chen'),('Description','An honest conversation with UBC founders about finding a first customer, building a team, and starting before you feel ready. Q&A and community introductions to follow.'),('Capacity','100')]:
 kit+=f'<div class="event-copy"><div><span class="field-label">{label}</span><p>{value}</p></div><button class="btn" data-copy>Copy {label.lower()}</button></div>'
kit+='<img class="event-cover" src="../img/buildher-wide.webp" alt="Sample club photo for event cover"><a class="btn" download="founder-stories-cover.webp" href="../img/buildher-wide.webp">Download cover image</a><p class="field-hint">Sample cover; use approved artwork for the real event.</p><a class="btn btn--primary" href="https://lu.ma/create" target="_blank" rel="noopener">Open Luma create ↗ (new tab)</a><form id="luma-form" class="stack">'+field('Paste Luma URL','<input class="input" id="luma-url" type="url" placeholder="https://lu.ma/your-event" required aria-describedby="link-state">')+'<p id="link-state" class="notice" role="status">Unlinked · Attendee data is imported by CSV.</p><button class="btn" type="submit">Save Luma link</button></form><section class="stack"><h3>Notion event page <span class="badge">Coming soon</span></h3>'+field('Notion page link','<input class="input" disabled placeholder="Notion page link will appear here">')+'<p class="field-hint">Placeholder only. No page is created or synced yet.</p></section><p id="copy-status" role="status"></p>'
imp=field('Event',f'<select class="select"><option>{name}</option><option>Design for people</option></select>')+'<label class="dropzone">Choose Luma CSV · guest list, check-ins or reflections<input type="file" accept=".csv"></label><p class="notice">Preview before import. Existing guests match by email.</p>'+table(['Guest','Action'],[['Jamie Wong · jamie@ubc.ca','Update check-in'],['Sam Rivera · sam@ubc.ca','Add guest']],caption='Sample CSV preview')+'<p class="notice notice--negative" role="alert">Row 14: missing email. Fix this row and upload again; nothing has been imported.</p>'+button('Choose corrected CSV',extra='id="correct-csv"')+button('Import 2 guests',True,'id="import-guests" disabled')+'<p id="import-status" role="status"></p>'
design=field('Type','<select class="select"><option>Event promotion</option><option>Print</option><option>Presentation</option></select>')+inp('Title','Founder stories · event promotion')+field('Linked event',f'<input class="input" value="{name}" readonly>')+inp('Due date','2026-11-06','date')+inp('Sizes / formats','Instagram 1080 × 1350 · Story 1080 × 1920 · Luma cover')+field('Brief','<textarea class="textarea">Promote the Nov 12 founder conversation at The Nest. Include 6–8 PM, UBC, and space for the Luma registration link.</textarea>')+inp('References (optional)','')+'<p class="field-hint">Creates a New request on the Design board. Designers self-assign.</p>'+button('Create design request',True,'id="request-design"')+'<p id="design-status" role="status"></p>'
health=block('Event health · Fall venture night',kpis([('Registered','112','CSV · Oct 29, 9:12 AM'),('Checked in','97','87% of registrations'),('Reflections','68','70% of attendees')])+'<p class="notice notice--attention">15 registered guests did not check in. 29 attendees have no reflection yet.</p><p class="small muted">Figures update after a CSV import; they are not live Luma totals.</p>')
states=block('Preview states','<div class="action-row">'+''.join(button(t,extra=f'data-state="{k}"') for k,t in [('ready','Ready'),('empty','Empty'),('loading','Loading'),('error','Error')])+'</div><div id="state-empty" class="state" hidden><h3 class="state-title">No events yet</h3><p class="state-body">Plan your next CSEED gathering or import an existing Luma event.</p>'+button('Create first event',extra='data-open="editor"')+'</div><div id="state-loading" class="state" hidden aria-busy="true" role="status"><p>Loading events…</p><div class="skel skel--row"></div></div><div id="state-error" class="state state--error" hidden role="alert"><h3 class="state-title">Events couldn’t load</h3><p>Your saved drafts are safe. Try again.</p>'+button('Retry',extra='data-state="ready"')+'</div>')
roles=block('Role preview','<p class="small muted">Event actions are available to every officer. Leadership and owners inherit director access; owner is a flag on leadership.</p>'+field('Preview as','<select class="select" id="role"><option>Officer</option><option selected>Director</option><option>Leadership</option><option>Owner</option></select>')+'<p id="role-note" role="status">Director · Create, edit, delete, import CSV and request design.</p>')
dialogs=dialog('editor','Event editor',editor,True)+dialog('handoff','Luma handoff kit',kit,True)+dialog('import','Import event data',imp)+dialog('design','Request design',design)+dialog('delete','Delete event?','<p>Delete Founder stories from the dashboard? The published Luma event must be removed separately.</p>'+button('Cancel',extra='data-close')+button('Delete draft',extra='id="confirm-delete" class="btn btn--danger"'))
html=shell('events','Events','Plan the gathering. Keep the handoff together.',controls+views+health+states+roles,dialogs).replace('</head>','<link rel="stylesheet" href="../v03.css"></head>')
html=html.replace('<html lang="en"','<html class="events-v03" lang="en"').replace('class="btn" id="confirm-delete" class="btn btn--danger"','class="btn btn--danger" id="confirm-delete"')
html=html.replace('</body>', '''<script>
const openers=new Map();
document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{const d=document.getElementById(b.dataset.open);openers.set(d,b);if(b.dataset.open==='editor')document.getElementById('event-form').reset();if(b.hasAttribute('data-new')){document.querySelectorAll('#event-form input,#event-form textarea').forEach(e=>e.value='');document.getElementById('saved').textContent='New event · Add the details, then save your draft.'}d.showModal()});
document.querySelectorAll('dialog').forEach(d=>{d.setAttribute('aria-label',d.querySelector('h2')?.textContent||'Search');d.addEventListener('close',()=>openers.get(d)?.focus())});
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(t=>{t.setAttribute('aria-pressed',t===b);document.getElementById('view-'+t.dataset.view).hidden=t!==b});document.getElementById('period').textContent=b.dataset.view==='list'?'Fall term · 4 events':'November 2026';document.getElementById('filter').disabled=b.dataset.view!=='list'});
document.querySelectorAll('[data-state]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[id^="state-"]').forEach(s=>s.hidden=s.id!=='state-'+b.dataset.state);document.querySelectorAll('[id^="view-"]').forEach(s=>s.hidden=b.dataset.state!=='ready'||s.id!=='view-'+document.querySelector('[data-view][aria-pressed=true]').dataset.view)});
document.getElementById('filter').oninput=e=>{let count=0;document.querySelectorAll('#view-list tbody tr').forEach(r=>{r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase());if(!r.hidden)count++});document.getElementById('period').textContent=e.target.value?count+' matching events':'Fall term · 4 events'};
document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.previousElementSibling.querySelector('p').textContent);b.textContent='Copied ✓';document.getElementById('copy-status').textContent='Field copied.'}catch{document.getElementById('copy-status').textContent='Copy unavailable. Select the field text and copy it manually.'}});
document.getElementById('event-form').onsubmit=e=>{e.preventDefault();document.getElementById('saved').textContent='Draft saved in this preview. Open its Luma handoff kit from the list.'};
document.getElementById('luma-form').onsubmit=e=>{e.preventDefault();const u=new URL(document.getElementById('luma-url').value);const ok=['lu.ma','luma.com','www.lu.ma','www.luma.com'].includes(u.hostname)&&u.protocol==='https:'&&u.pathname!=='/'&&!['/create','/create/'].includes(u.pathname);document.getElementById('luma-url').setAttribute('aria-invalid',!ok);document.getElementById('link-state').className='notice '+(ok?'notice--positive':'notice--negative');document.getElementById('link-state').setAttribute('role',ok?'status':'alert');document.getElementById('link-state').textContent=ok?'Linked ✓ · '+u.href+' · CSV imports still required.':'Use an HTTPS event URL on lu.ma or luma.com.'};
document.getElementById('request-design').onclick=e=>{e.target.disabled=true;document.getElementById('design-status').textContent='Design request created · New · Founder stories · event promotion (preview).'};
document.getElementById('confirm-delete').onclick=()=>{document.getElementById('delete').close();document.getElementById('editor').close();document.querySelector('#view-list tbody tr').hidden=true;document.querySelectorAll('.cal-event.is-draft,.cal-block').forEach(e=>e.hidden=true);document.getElementById('period').textContent='Draft deleted · Preview only'};
document.getElementById('correct-csv').onclick=()=>document.querySelector('#import input[type=file]').click();
document.querySelector('#import input[type=file]').onchange=()=>{document.querySelector('#import [role=alert]').hidden=true;document.getElementById('import-guests').disabled=false;document.getElementById('import-status').textContent='Preview: 2 valid guests, ready to import (sample).'};
document.getElementById('import-guests').onclick=e=>{e.target.disabled=true;document.getElementById('import-status').textContent='Imported 2 guests · 1 added, 1 updated (preview).'};
document.getElementById('role').onchange=e=>{document.querySelector('.user-chip-role').textContent=e.target.value;document.documentElement.dataset.role=e.target.value==='Owner'?'leadership':e.target.value.toLowerCase();document.getElementById('role-note').textContent=e.target.value+' · Create, edit, delete, import CSV and request design.'};
</script></body>''')
(out/'events-v03.html').write_text(html)
